INSERT INTO mal_aptitude_question_bank ("വിഷയം", "ഭാഷ", "ചോദ്യത്തിന്റെ തരം", "കഠിനത", "മാർക്ക്", "ചോദ്യം", "ഓപ്ഷൻ അ", "ഓപ്ഷൻ ആ", "ഓപ്ഷൻ ഇ", "ഓപ്ഷൻ ഈ", "ശരിയായ ഉത്തരം", "വിശദീകരണം") VALUES
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു സംഖ്യയുടെ 20 ശതമാനം 50 ആണെങ്കിൽ ആ സംഖ്യ ഏത്?', '200', '250', '300', '150', 'ആ', '50 ÷ 0.20 = 250.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '12, 18, 24, 30 എന്ന ശ്രേണിയിലെ അടുത്ത സംഖ്യ ഏത്?', '34', '36', '38', '40', 'ആ', 'ഓരോ ഘട്ടത്തിലും 6 വീതം കൂട്ടുന്നു.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു വസ്തുവിന്റെ വില 500 രൂപ. 10 ശതമാനം ഇളവ് നൽകിയാൽ വിൽപ്പന വില എത്ര?', '450 രൂപ', '460 രൂപ', '480 രൂപ', '490 രൂപ', 'അ', '500 - 50 = 450 രൂപ.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '3 : 5 എന്ന അനുപാതത്തിൽ ആദ്യ സംഖ്യ 21 ആണെങ്കിൽ രണ്ടാമത്തെ സംഖ്യ എത്ര?', '28', '30', '35', '40', 'ഇ', '21 × 5 ÷ 3 = 35.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു വാഹനം മണിക്കൂറിൽ 60 കിലോമീറ്റർ വേഗത്തിൽ 3 മണിക്കൂർ സഞ്ചരിച്ചാൽ ദൂരം എത്ര?', '120 കി.മീ.', '150 കി.മീ.', '180 കി.മീ.', '200 കി.മീ.', 'ഇ', 'ദൂരം = വേഗം × സമയം = 60 × 3 = 180.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '250ന്റെ 4 ശതമാനം എത്ര?', '8', '10', '12', '15', 'ആ', '250 × 4 ÷ 100 = 10.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു സംഖ്യയിൽ 25 ചേർത്തപ്പോൾ 75 ലഭിച്ചു. സംഖ്യ ഏത്?', '40', '45', '50', '55', 'ഇ', '75 - 25 = 50.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '2, 4, 8, 16 എന്ന ശ്രേണിയിലെ അടുത്ത സംഖ്യ ഏത്?', '24', '30', '32', '36', 'ഇ', 'ഓരോ സംഖ്യയും 2 കൊണ്ട് ഗുണിക്കുന്നു.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '5 തൊഴിലാളികൾ ഒരു ജോലി 12 ദിവസത്തിൽ പൂർത്തിയാക്കുന്നു. അതേ നിരക്കിൽ 10 തൊഴിലാളികൾക്ക് എത്ര ദിവസം വേണം?', '4', '5', '6', '8', 'ഇ', 'തൊഴിലാളികളുടെ എണ്ണം ഇരട്ടിയാകുമ്പോൾ സമയം പകുതിയാകും.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു സംഖ്യയുടെ പകുതി 36 ആണെങ്കിൽ സംഖ്യ ഏത്?', '54', '60', '72', '84', 'ഇ', '36 × 2 = 72.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു ചതുരത്തിന്റെ വശം 8 സെ.മീ. ആണെങ്കിൽ പരിസരം എത്ര?', '16 സെ.മീ.', '24 സെ.മീ.', '32 സെ.മീ.', '64 സെ.മീ.', 'ഇ', 'പരിസരം = 4 × 8 = 32 സെ.മീ.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു ആയതത്തിന്റെ നീളം 10 സെ.മീ.യും വീതി 6 സെ.മീ.യും ആണെങ്കിൽ വിസ്തീർണ്ണം എത്ര?', '16 ച.സെ.മീ.', '32 ച.സെ.മീ.', '60 ച.സെ.മീ.', '120 ച.സെ.മീ.', 'ഇ', 'വിസ്തീർണ്ണം = നീളം × വീതി = 60.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '1000 രൂപയ്ക്ക് വർഷത്തിൽ 5 ശതമാനം ലളിത പലിശ നിരക്കിൽ 2 വർഷത്തെ പലിശ എത്ര?', '50 രൂപ', '75 രൂപ', '100 രൂപ', '150 രൂപ', 'ഇ', 'പലിശ = 1000 × 5 × 2 ÷ 100 = 100.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു പരീക്ഷയിൽ 80ൽ 60 മാർക്ക് ലഭിച്ചു. ശതമാനം എത്ര?', '60%', '70%', '75%', '80%', 'ഇ', '60 ÷ 80 × 100 = 75%.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു സംഖ്യ 20 ശതമാനം വർധിച്ച് 120 ആയി. ആദ്യ സംഖ്യ എത്ര?', '90', '100', '110', '115', 'ആ', '120 ÷ 1.20 = 100.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '7 × 8 - 12 ന്റെ മൂല്യം എത്ര?', '42', '44', '46', '48', 'ആ', '56 - 12 = 44.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '36ന്റെ ഏറ്റവും വലിയ ഘടകം ഏത്?', '6', '12', '18', '36', 'ഈ', 'ഒരു സംഖ്യയുടെ ഏറ്റവും വലിയ ഘടകം ആ സംഖ്യ തന്നെയാണ്.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '18നും 24നും ഉള്ള ഏറ്റവും വലിയ പൊതു ഘടകം ഏത്?', '3', '6', '9', '12', 'ആ', '18, 24 എന്നിവയുടെ ഏറ്റവും വലിയ പൊതു ഘടകം 6 ആണ്.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '6നും 8നും ഉള്ള ഏറ്റവും ചെറിയ പൊതു ഗുണകം ഏത്?', '12', '18', '24', '48', 'ഇ', '6ന്റെയും 8ന്റെയും ഏറ്റവും ചെറിയ പൊതു ഗുണകം 24 ആണ്.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു ക്ലോക്കിൽ 3 മണിക്ക് മണിക്കൂർ സൂചിയും മിനിറ്റ് സൂചിയും തമ്മിലുള്ള കോണം എത്ര?', '60°', '90°', '120°', '180°', 'ആ', '3 മണിക്ക് സൂചികൾ പരസ്പരം ലംബമാണ്.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു കിലോമീറ്ററിൽ എത്ര മീറ്റർ?', '100', '500', '1000', '1500', 'ഇ', '1 കിലോമീറ്റർ = 1000 മീറ്റർ.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു വസ്തുവിന്റെ വാങ്ങുവില 800 രൂപയും വിൽപ്പനവില 920 രൂപയും ആണെങ്കിൽ ലാഭം എത്ര?', '100', '120', '140', '160', 'ആ', '920 - 800 = 120 രൂപ.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു സംഖ്യയുടെ 3/5 ഭാഗം 24 ആണെങ്കിൽ സംഖ്യ ഏത്?', '30', '36', '40', '45', 'ഇ', '24 × 5 ÷ 3 = 40.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'രണ്ട് സംഖ്യകളുടെ ശരാശരി 25 ആണ്. ഒന്നാമത്തെ സംഖ്യ 20 ആണെങ്കിൽ രണ്ടാമത്തേത് എത്ര?', '25', '30', '35', '40', 'ആ', 'രണ്ടു സംഖ്യകളുടെ ആകെ 50; 50 - 20 = 30.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു വ്യക്തി 500 രൂപ ചെലവഴിച്ച് 1000 രൂപ സമ്പാദിച്ചു. ആകെ തുക എത്ര?', '500', '1000', '1500', '2000', 'ഇ', '500 + 1000 = 1500.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '9, 18, 27, 36 എന്ന ശ്രേണിയിലെ അടുത്ത സംഖ്യ ഏത്?', '42', '45', '48', '54', 'ആ', 'ഓരോ ഘട്ടത്തിലും 9 വീതം കൂട്ടുന്നു.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു ത്രികോണത്തിന്റെ മൂന്ന് കോണുകളുടെ ആകെ തുക എത്ര?', '90°', '180°', '270°', '360°', 'ആ', 'ത്രികോണത്തിലെ കോണുകളുടെ ആകെ തുക 180° ആണ്.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു സംഖ്യയുടെ 10 ശതമാനം 7 ആണെങ്കിൽ സംഖ്യ ഏത്?', '50', '60', '70', '80', 'ഇ', '7 × 100 ÷ 10 = 70.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു ജോലി 15 ദിവസത്തിൽ പൂർത്തിയാക്കുന്ന ഒരാൾക്ക് അതേ ജോലി 5 ദിവസത്തിൽ പൂർത്തിയാക്കാൻ എത്രമടങ്ങ് വേഗം വേണം?', '2', '3', '4', '5', 'ആ', '15 ÷ 5 = 3 മടങ്ങ്.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു ബാഗിന്റെ വില 1200 രൂപ. 15 ശതമാനം ഇളവ് നൽകിയാൽ ഇളവ് തുക എത്ര?', '120', '150', '180', '200', 'ഇ', '1200 × 15 ÷ 100 = 180.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു സംഖ്യ 5 കൊണ്ട് ഹരിച്ചപ്പോൾ ശിഷ്ടം 2. താഴെപ്പറയുന്നവയിൽ സാധ്യമായ സംഖ്യ ഏത്?', '20', '22', '25', '30', 'ആ', '22 നെ 5 കൊണ്ട് ഹരിച്ചാൽ ശിഷ്ടം 2.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു വ്യക്തി മണിക്കൂറിൽ 5 കിലോമീറ്റർ നടക്കുന്നു. 4 മണിക്കൂറിൽ ദൂരം എത്ര?', '15', '20', '25', '30', 'ആ', '5 × 4 = 20 കി.മീ.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു ആയതത്തിന്റെ നീളം 12 സെ.മീ., വീതി 5 സെ.മീ. ആണെങ്കിൽ പരിസരം എത്ര?', '17', '24', '34', '60', 'ഇ', 'പരിസരം = 2(12+5) = 34.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു സംഖ്യയിൽ നിന്ന് 18 കുറച്ചപ്പോൾ 42 ലഭിച്ചു. സംഖ്യ ഏത്?', '54', '60', '62', '70', 'ആ', '42 + 18 = 60.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', '4, 9, 14, 19 എന്ന ശ്രേണിയിലെ അടുത്ത സംഖ്യ ഏത്?', '22', '23', '24', '25', 'ഇ', 'ഓരോ ഘട്ടത്തിലും 5 വീതം കൂട്ടുന്നു; അടുത്തത് 24.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു സംഖ്യയുടെ 75 ശതമാനം 45 ആണെങ്കിൽ സംഖ്യ ഏത്?', '50', '55', '60', '65', 'ഇ', '45 ÷ 0.75 = 60.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'ഒരു കുടുംബത്തിന്റെ മാസവരുമാനം 30000 രൂപ. അതിൽ 20 ശതമാനം സംരക്ഷിച്ചാൽ സംരക്ഷണം എത്ര?', '5000', '6000', '7000', '8000', 'ആ', '30000 × 20 ÷ 100 = 6000.'),
