('MAL-Aptitude', 'മലയാളം', 'ശൂന്യസ്ഥലം പൂരിപ്പിക്കുക', 'എളുപ്പം', '1', 'ഒരു ദിവസത്തിൽ ______ മണിക്കൂർ ഉണ്ട്.', '', '', '', '', '24', 'ശരിയായ ഉത്തരം: 24.'),
('MAL-Aptitude', 'മലയാളം', 'ശൂന്യസ്ഥലം പൂരിപ്പിക്കുക', 'എളുപ്പം', '1', '2നും 3നും ഉള്ള ഏറ്റവും ചെറിയ പൊതു ഗുണകം ______ ആണ്.', '', '', '', '', '6', 'ശരിയായ ഉത്തരം: 6.'),
('MAL-Aptitude', 'മലയാളം', 'ശൂന്യസ്ഥലം പൂരിപ്പിക്കുക', 'എളുപ്പം', '1', '12ന്റെ ഏറ്റവും വലിയ പൊതു ഘടകം 18നോട് ചേർന്ന് കണക്കാക്കുമ്പോൾ ______ ആണ്.', '', '', '', '', '6', 'ശരിയായ ഉത്തരം: 6.'),
('MAL-Aptitude', 'മലയാളം', 'ശൂന്യസ്ഥലം പൂരിപ്പിക്കുക', 'എളുപ്പം', '1', '1000 രൂപയുടെ 5% ______ രൂപയാണ്.', '', '', '', '', '50', 'ശരിയായ ഉത്തരം: 50.'),
('MAL-Aptitude', 'മലയാളം', 'ശൂന്യസ്ഥലം പൂരിപ്പിക്കുക', 'എളുപ്പം', '1', '500 രൂപയുടെ 20% ______ രൂപയാണ്.', '', '', '', '', '100', 'ശരിയായ ഉത്തരം: 100.'),
('MAL-Aptitude', 'മലയാളം', 'ശൂന്യസ്ഥലം പൂരിപ്പിക്കുക', 'എളുപ്പം', '1', 'ഒരു സംഖ്യയുടെ 25% 20 ആണെങ്കിൽ ആ സംഖ്യ ______ ആണ്.', '', '', '', '', '80', 'ശരിയായ ഉത്തരം: 80.'),
('MAL-Aptitude', 'മലയാളം', 'ശൂന്യസ്ഥലം പൂരിപ്പിക്കുക', 'എളുപ്പം', '1', '3:5 എന്ന അനുപാതത്തിൽ ആദ്യ സംഖ്യ 12 ആണെങ്കിൽ രണ്ടാമത്തെ സംഖ്യ ______ ആണ്.', '', '', '', '', '20', 'ശരിയായ ഉത്തരം: 20.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ശതമാനം എന്നത് എന്താണ്?', '', '', '', '', '100നെ അടിസ്ഥാനമാക്കി ഒരു അളവിനെ പ്രകടിപ്പിക്കുന്ന രീതിയാണ് ശതമാനം.', '100നെ അടിസ്ഥാനമാക്കി ഒരു അളവിനെ പ്രകടിപ്പിക്കുന്ന രീതിയാണ് ശതമാനം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'അനുപാതം എന്താണ്?', '', '', '', '', 'രണ്ട് അളവുകളുടെ താരതമ്യം അനുപാതം എന്നറിയപ്പെടുന്നു.', 'രണ്ട് അളവുകളുടെ താരതമ്യം അനുപാതം എന്നറിയപ്പെടുന്നു.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ശരാശരി എങ്ങനെ കണ്ടെത്താം?', '', '', '', '', 'എല്ലാ മൂല്യങ്ങളുടെയും ആകെ തുകയെ മൂല്യങ്ങളുടെ എണ്ണത്തിൽ ഹരിക്കണം.', 'എല്ലാ മൂല്യങ്ങളുടെയും ആകെ തുകയെ മൂല്യങ്ങളുടെ എണ്ണത്തിൽ ഹരിക്കണം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ലാഭം എങ്ങനെ കണക്കാക്കാം?', '', '', '', '', 'വിൽപ്പനവിലയിൽ നിന്ന് വാങ്ങുവില കുറച്ചാൽ ലാഭം ലഭിക്കും.', 'വിൽപ്പനവിലയിൽ നിന്ന് വാങ്ങുവില കുറച്ചാൽ ലാഭം ലഭിക്കും.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'നഷ്ടം എങ്ങനെ കണക്കാക്കാം?', '', '', '', '', 'വാങ്ങുവിലയിൽ നിന്ന് വിൽപ്പനവില കുറച്ചാൽ നഷ്ടം ലഭിക്കും.', 'വാങ്ങുവിലയിൽ നിന്ന് വിൽപ്പനവില കുറച്ചാൽ നഷ്ടം ലഭിക്കും.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'വേഗത്തിന്റെ സൂത്രവാക്യം എന്താണ്?', '', '', '', '', 'വേഗം = ദൂരം ÷ സമയം.', 'വേഗം = ദൂരം ÷ സമയം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ദൂരത്തിന്റെ സൂത്രവാക്യം എന്താണ്?', '', '', '', '', 'ദൂരം = വേഗം × സമയം.', 'ദൂരം = വേഗം × സമയം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'സമയത്തിന്റെ സൂത്രവാക്യം എന്താണ്?', '', '', '', '', 'സമയം = ദൂരം ÷ വേഗം.', 'സമയം = ദൂരം ÷ വേഗം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ലളിത പലിശ എന്താണ്?', '', '', '', '', 'മൂലധനത്തിന് നിശ്ചിത നിരക്കിലും കാലയളവിലും ലഭിക്കുന്ന പലിശയാണ് ലളിത പലിശ.', 'മൂലധനത്തിന് നിശ്ചിത നിരക്കിലും കാലയളവിലും ലഭിക്കുന്ന പലിശയാണ് ലളിത പലിശ.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'അഭാജ്യ സംഖ്യ എന്താണ്?', '', '', '', '', 'ഒന്നിനും ആ സംഖ്യയ്ക്കുമല്ലാതെ മറ്റൊരു ഘടകമില്ലാത്ത സംഖ്യയാണ് അഭാജ്യ സംഖ്യ.', 'ഒന്നിനും ആ സംഖ്യയ്ക്കുമല്ലാതെ മറ്റൊരു ഘടകമില്ലാത്ത സംഖ്യയാണ് അഭാജ്യ സംഖ്യ.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ഇരട്ട സംഖ്യ എന്താണ്?', '', '', '', '', '2 കൊണ്ട് പൂർണ്ണമായി ഹരിക്കാവുന്ന സംഖ്യയാണ് ഇരട്ട സംഖ്യ.', '2 കൊണ്ട് പൂർണ്ണമായി ഹരിക്കാവുന്ന സംഖ്യയാണ് ഇരട്ട സംഖ്യ.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ഒറ്റ സംഖ്യ എന്താണ്?', '', '', '', '', '2 കൊണ്ട് പൂർണ്ണമായി ഹരിക്കാനാകാത്ത സംഖ്യയാണ് ഒറ്റ സംഖ്യ.', '2 കൊണ്ട് പൂർണ്ണമായി ഹരിക്കാനാകാത്ത സംഖ്യയാണ് ഒറ്റ സംഖ്യ.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ഏറ്റവും വലിയ പൊതു ഘടകം എന്താണ്?', '', '', '', '', 'രണ്ട് അല്ലെങ്കിൽ കൂടുതൽ സംഖ്യകളെ പൂർണ്ണമായി ഹരിക്കുന്ന ഏറ്റവും വലിയ സംഖ്യയാണ് ഏറ്റവും വലിയ പൊതു ഘടകം.', 'രണ്ട് അല്ലെങ്കിൽ കൂടുതൽ സംഖ്യകളെ പൂർണ്ണമായി ഹരിക്കുന്ന ഏറ്റവും വലിയ സംഖ്യയാണ് ഏറ്റവും വലിയ പൊതു ഘടകം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ഏറ്റവും ചെറിയ പൊതു ഗുണകം എന്താണ്?', '', '', '', '', 'രണ്ട് അല്ലെങ്കിൽ കൂടുതൽ സംഖ്യകളുടെ പൊതു ഗുണിതങ്ങളിൽ ഏറ്റവും ചെറിയതാണത്.', 'രണ്ട് അല്ലെങ്കിൽ കൂടുതൽ സംഖ്യകളുടെ പൊതു ഗുണിതങ്ങളിൽ ഏറ്റവും ചെറിയതാണത്.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ഭിന്നസംഖ്യ എന്താണ്?', '', '', '', '', 'ഒരു പൂർണ്ണതയുടെ ഭാഗത്തെ പ്രതിനിധീകരിക്കുന്ന സംഖ്യയാണ് ഭിന്നസംഖ്യ.', 'ഒരു പൂർണ്ണതയുടെ ഭാഗത്തെ പ്രതിനിധീകരിക്കുന്ന സംഖ്യയാണ് ഭിന്നസംഖ്യ.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ദശാംശ സംഖ്യ എന്താണ്?', '', '', '', '', 'ദശാംശ ബിന്ദു ഉപയോഗിച്ച് ഭാഗിക മൂല്യം പ്രകടിപ്പിക്കുന്ന സംഖ്യയാണ് ദശാംശ സംഖ്യ.', 'ദശാംശ ബിന്ദു ഉപയോഗിച്ച് ഭാഗിക മൂല്യം പ്രകടിപ്പിക്കുന്ന സംഖ്യയാണ് ദശാംശ സംഖ്യ.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ചതുരത്തിന്റെ വിസ്തീർണ്ണം എങ്ങനെ കണ്ടെത്താം?', '', '', '', '', 'വശം × വശം എന്നതാണ് ചതുരത്തിന്റെ വിസ്തീർണ്ണം.', 'വശം × വശം എന്നതാണ് ചതുരത്തിന്റെ വിസ്തീർണ്ണം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ചതുരത്തിന്റെ പരിസരം എങ്ങനെ കണ്ടെത്താം?', '', '', '', '', '4 × വശം എന്നതാണ് ചതുരത്തിന്റെ പരിസരം.', '4 × വശം എന്നതാണ് ചതുരത്തിന്റെ പരിസരം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ആയതത്തിന്റെ പരിസരം എങ്ങനെ കണ്ടെത്താം?', '', '', '', '', '2 × (നീളം + വീതി) എന്നതാണ് പരിസരം.', '2 × (നീളം + വീതി) എന്നതാണ് പരിസരം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ആയതത്തിന്റെ വിസ്തീർണ്ണം എങ്ങനെ കണ്ടെത്താം?', '', '', '', '', 'നീളം × വീതി എന്നതാണ് വിസ്തീർണ്ണം.', 'നീളം × വീതി എന്നതാണ് വിസ്തീർണ്ണം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ശതമാനം വർധന എന്താണ്?', '', '', '', '', 'ആദ്യ മൂല്യവുമായി താരതമ്യം ചെയ്യുമ്പോൾ ഉണ്ടായ വർധനയെ ശതമാനമായി പ്രകടിപ്പിച്ചതാണ് ശതമാനം വർധന.', 'ആദ്യ മൂല്യവുമായി താരതമ്യം ചെയ്യുമ്പോൾ ഉണ്ടായ വർധനയെ ശതമാനമായി പ്രകടിപ്പിച്ചതാണ് ശതമാനം വർധന.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ശതമാനം കുറവ് എന്താണ്?', '', '', '', '', 'ആദ്യ മൂല്യവുമായി താരതമ്യം ചെയ്യുമ്പോൾ ഉണ്ടായ കുറവിനെ ശതമാനമായി പ്രകടിപ്പിച്ചതാണ് ശതമാനം കുറവ്.', 'ആദ്യ മൂല്യവുമായി താരതമ്യം ചെയ്യുമ്പോൾ ഉണ്ടായ കുറവിനെ ശതമാനമായി പ്രകടിപ്പിച്ചതാണ് ശതമാനം കുറവ്.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'അനുപാതം ലഘൂകരിക്കുന്നത് എങ്ങനെ?', '', '', '', '', 'അനുപാതത്തിലെ രണ്ട് പദങ്ങളെയും അവയുടെ പൊതുഘടകത്തിൽ ഹരിച്ചാൽ ലഘൂകരിക്കാം.', 'അനുപാതത്തിലെ രണ്ട് പദങ്ങളെയും അവയുടെ പൊതുഘടകത്തിൽ ഹരിച്ചാൽ ലഘൂകരിക്കാം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'ജോലി-സമയം പ്രശ്നങ്ങളിൽ പ്രധാന ആശയം എന്താണ്?', '', '', '', '', 'ജോലി സ്ഥിരമാണെങ്കിൽ തൊഴിലാളികളുടെ എണ്ണം കൂടുമ്പോൾ ആവശ്യമായ സമയം കുറയും.', 'ജോലി സ്ഥിരമാണെങ്കിൽ തൊഴിലാളികളുടെ എണ്ണം കൂടുമ്പോൾ ആവശ്യമായ സമയം കുറയും.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'സംഖ്യാ ശ്രേണി എന്താണ്?', '', '', '', '', 'ഒരു നിയമമനുസരിച്ച് ക്രമമായി എഴുതിയ സംഖ്യകളുടെ പട്ടികയാണ് സംഖ്യാ ശ്രേണി.', 'ഒരു നിയമമനുസരിച്ച് ക്രമമായി എഴുതിയ സംഖ്യകളുടെ പട്ടികയാണ് സംഖ്യാ ശ്രേണി.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'വർഗം എന്താണ്?', '', '', '', '', 'ഒരു സംഖ്യയെ അതേ സംഖ്യകൊണ്ട് ഗുണിച്ചാൽ ലഭിക്കുന്ന ഫലമാണ് വർഗം.', 'ഒരു സംഖ്യയെ അതേ സംഖ്യകൊണ്ട് ഗുണിച്ചാൽ ലഭിക്കുന്ന ഫലമാണ് വർഗം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'വർഗമൂലം എന്താണ്?', '', '', '', '', 'ഒരു സംഖ്യയെ സ്വയം ഗുണിച്ചാൽ നൽകിയ സംഖ്യ ലഭിക്കുന്ന സംഖ്യയാണ് വർഗമൂലം.', 'ഒരു സംഖ്യയെ സ്വയം ഗുണിച്ചാൽ നൽകിയ സംഖ്യ ലഭിക്കുന്ന സംഖ്യയാണ് വർഗമൂലം.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'പ്രായ പ്രശ്നങ്ങളിൽ സാധാരണ ഉപയോഗിക്കുന്ന ആശയം എന്താണ്?', '', '', '', '', 'വ്യക്തികളുടെ പ്രായവ്യത്യാസം സമയത്തിനനുസരിച്ച് സ്ഥിരമായി തുടരുന്നു.', 'വ്യക്തികളുടെ പ്രായവ്യത്യാസം സമയത്തിനനുസരിച്ച് സ്ഥിരമായി തുടരുന്നു.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'വസ്തുവിന്റെ വാങ്ങുവില എന്താണ്?', '', '', '', '', 'ഒരു വസ്തു വാങ്ങാൻ നൽകിയ തുകയാണ് വാങ്ങുവില.', 'ഒരു വസ്തു വാങ്ങാൻ നൽകിയ തുകയാണ് വാങ്ങുവില.'),
('MAL-Aptitude', 'മലയാളം', 'സംക്ഷിപ്ത ഉത്തരം', 'മധ്യമം', '2', 'വസ്തുവിന്റെ വിൽപ്പനവില എന്താണ്?', '', '', '', '', 'ഒരു വസ്തു വിൽക്കുമ്പോൾ ലഭിക്കുന്ന തുകയാണ് വിൽപ്പനവില.', 'ഒരു വസ്തു വിൽക്കുമ്പോൾ ലഭിക്കുന്ന തുകയാണ് വിൽപ്പനവില.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', '1200 രൂപയുടെ 15% കണ്ടെത്തി കണക്കാക്കുന്ന രീതി വിശദീകരിക്കുക.', '', '', '', '', '1200 × 15 ÷ 100 = 180. അതിനാൽ 1200 രൂപയുടെ 15% 180 രൂപയാണ്.', '1200 × 15 ÷ 100 = 180. അതിനാൽ 1200 രൂപയുടെ 15% 180 രൂപയാണ്.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', '800 രൂപ വാങ്ങുവിലയുള്ള വസ്തു 920 രൂപയ്ക്ക് വിറ്റാൽ ലാഭവും ലാഭശതമാനവും കണ്ടെത്തുക.', '', '', '', '', 'ലാഭം = 920 - 800 = 120 രൂപ. ലാഭശതമാനം = 120 ÷ 800 × 100 = 15%.', 'ലാഭം = 920 - 800 = 120 രൂപ. ലാഭശതമാനം = 120 ÷ 800 × 100 = 15%.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', '60 കിലോമീറ്റർ/മണിക്കൂർ വേഗത്തിൽ 4 മണിക്കൂർ സഞ്ചരിക്കുന്ന വാഹനത്തിന്റെ ദൂരം കണ്ടെത്തുക.', '', '', '', '', 'ദൂരം = വേഗം × സമയം = 60 × 4 = 240 കിലോമീറ്റർ.', 'ദൂരം = വേഗം × സമയം = 60 × 4 = 240 കിലോമീറ്റർ.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', '5000 രൂപയ്ക്ക് 6% നിരക്കിൽ 2 വർഷത്തെ ലളിത പലിശ കണ്ടെത്തുക.', '', '', '', '', 'ലളിത പലിശ = 5000 × 6 × 2 ÷ 100 = 600 രൂപ.', 'ലളിത പലിശ = 5000 × 6 × 2 ÷ 100 = 600 രൂപ.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു സംഖ്യയുടെ 3/5 ഭാഗം 48 ആണെങ്കിൽ സംഖ്യ കണ്ടെത്തുക.', '', '', '', '', 'സംഖ്യ = 48 × 5 ÷ 3 = 80.', 'സംഖ്യ = 48 × 5 ÷ 3 = 80.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു പരീക്ഷയിൽ 72ൽ 54 മാർക്ക് ലഭിച്ചാൽ ശതമാനം കണ്ടെത്തുക.', '', '', '', '', 'ശതമാനം = 54 ÷ 72 × 100 = 75%.', 'ശതമാനം = 54 ÷ 72 × 100 = 75%.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', '5 തൊഴിലാളികൾ 12 ദിവസത്തിൽ ജോലി പൂർത്തിയാക്കുന്നു. 10 തൊഴിലാളികൾക്ക് എത്ര ദിവസം വേുമെന്ന് വിശദീകരിക്കുക.', '', '', '', '', 'തൊഴിലാളികളുടെ എണ്ണം ഇരട്ടിയായതിനാൽ സമയം പകുതിയാകും. 12 ÷ 2 = 6 ദിവസം.', 'തൊഴിലാളികളുടെ എണ്ണം ഇരട്ടിയായതിനാൽ സമയം പകുതിയാകും. 12 ÷ 2 = 6 ദിവസം.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു ആയതത്തിന്റെ നീളം 15 സെ.മീ.യും വീതി 8 സെ.മീ.യും ആണെങ്കിൽ വിസ്തീർണ്ണവും പരിസരവും കണ്ടെത്തുക.', '', '', '', '', 'വിസ്തീർണ്ണം = 15 × 8 = 120 ച.സെ.മീ. പരിസരം = 2(15+8) = 46 സെ.മീ.', 'വിസ്തീർണ്ണം = 15 × 8 = 120 ച.സെ.മീ. പരിസരം = 2(15+8) = 46 സെ.മീ.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു ചതുരത്തിന്റെ വശം 12 സെ.മീ. ആണെങ്കിൽ വിസ്തീർണ്ണവും പരിസരവും കണ്ടെത്തുക.', '', '', '', '', 'വിസ്തീർണ്ണം = 12 × 12 = 144 ച.സെ.മീ. പരിസരം = 4 × 12 = 48 സെ.മീ.', 'വിസ്തീർണ്ണം = 12 × 12 = 144 ച.സെ.മീ. പരിസരം = 4 × 12 = 48 സെ.മീ.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', '20, 30, 40, 50 എന്നീ സംഖ്യകളുടെ ശരാശരി കണ്ടെത്തുക.', '', '', '', '', 'ആകെ = 140. എണ്ണം = 4. ശരാശരി = 140 ÷ 4 = 35.', 'ആകെ = 140. എണ്ണം = 4. ശരാശരി = 140 ÷ 4 = 35.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു വസ്തുവിന്റെ വില 2000 രൂപയിൽ നിന്ന് 2400 രൂപയായി. ശതമാനം വർധന കണ്ടെത്തുക.', '', '', '', '', 'വർധന = 400. ശതമാനം വർധന = 400 ÷ 2000 × 100 = 20%.', 'വർധന = 400. ശതമാനം വർധന = 400 ÷ 2000 × 100 = 20%.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു വസ്തുവിന്റെ വില 1500 രൂപയിൽ നിന്ന് 1200 രൂപയായി. ശതമാനം കുറവ് കണ്ടെത്തുക.', '', '', '', '', 'കുറവ് = 300. ശതമാനം കുറവ് = 300 ÷ 1500 × 100 = 20%.', 'കുറവ് = 300. ശതമാനം കുറവ് = 300 ÷ 1500 × 100 = 20%.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', '3:5 അനുപാതത്തിൽ ആകെ 64 ആണെങ്കിൽ രണ്ട് ഭാഗങ്ങൾ കണ്ടെത്തുക.', '', '', '', '', 'ആകെ ഭാഗങ്ങൾ = 8. ഒരു ഭാഗം = 64 ÷ 8 = 8. ഭാഗങ്ങൾ = 24, 40.', 'ആകെ ഭാഗങ്ങൾ = 8. ഒരു ഭാഗം = 64 ÷ 8 = 8. ഭാഗങ്ങൾ = 24, 40.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', '18നും 24നും ഉള്ള ഏറ്റവും വലിയ പൊതു ഘടകം കണ്ടെത്തുന്ന രീതി വിശദീകരിക്കുക.', '', '', '', '', '18ന്റെ ഘടകങ്ങൾ 1,2,3,6,9,18. 24ന്റെ ഘടകങ്ങളിൽ 1,2,3,4,6,8,12,24 ഉണ്ട്. ഏറ്റവും വലിയ പൊതു ഘടകം 6.', '18ന്റെ ഘടകങ്ങൾ 1,2,3,6,9,18. 24ന്റെ ഘടകങ്ങളിൽ 1,2,3,4,6,8,12,24 ഉണ്ട്. ഏറ്റവും വലിയ പൊതു ഘടകം 6.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', '6നും 8നും ഉള്ള ഏറ്റവും ചെറിയ പൊതു ഗുണകം കണ്ടെത്തുക.', '', '', '', '', '6ന്റെ ഗുണിതങ്ങൾ 6,12,18,24...; 8ന്റെ ഗുണിതങ്ങൾ 8,16,24...; അതിനാൽ ഏറ്റവും ചെറിയ പൊതു ഗുണകം 24.', '6ന്റെ ഗുണിതങ്ങൾ 6,12,18,24...; 8ന്റെ ഗുണിതങ്ങൾ 8,16,24...; അതിനാൽ ഏറ്റവും ചെറിയ പൊതു ഗുണകം 24.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു വ്യക്തി 5 കിലോമീറ്റർ/മണിക്കൂർ വേഗത്തിൽ 18 കിലോമീറ്റർ നടക്കുന്നു. സമയം കണ്ടെത്തുക.', '', '', '', '', 'സമയം = ദൂരം ÷ വേഗം = 18 ÷ 5 = 3.6 മണിക്കൂർ, അതായത് 3 മണിക്കൂർ 36 മിനിറ്റ്.', 'സമയം = ദൂരം ÷ വേഗം = 18 ÷ 5 = 3.6 മണിക്കൂർ, അതായത് 3 മണിക്കൂർ 36 മിനിറ്റ്.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു കുടുംബവരുമാനം 40000 രൂപ. 25% വാടകയ്ക്കും 15% ഭക്ഷണത്തിനും ചെലവഴിക്കുന്നു. രണ്ടിനും ചേർന്ന ചെലവ് കണ്ടെത്തുക.', '', '', '', '', 'ആകെ ശതമാനം = 40%. 40000 × 40 ÷ 100 = 16000 രൂപ.', 'ആകെ ശതമാനം = 40%. 40000 × 40 ÷ 100 = 16000 രൂപ.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു സംഖ്യ 25% വർധിച്ച് 250 ആയി. ആദ്യ സംഖ്യ കണ്ടെത്തുക.', '', '', '', '', 'ആദ്യ സംഖ്യ × 1.25 = 250. അതിനാൽ ആദ്യ സംഖ്യ = 250 ÷ 1.25 = 200.', 'ആദ്യ സംഖ്യ × 1.25 = 250. അതിനാൽ ആദ്യ സംഖ്യ = 250 ÷ 1.25 = 200.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു സംഖ്യ 20% കുറച്ച് 160 ആയി. ആദ്യ സംഖ്യ കണ്ടെത്തുക.', '', '', '', '', 'ആദ്യ സംഖ്യ × 0.80 = 160. അതിനാൽ ആദ്യ സംഖ്യ = 160 ÷ 0.8 = 200.', 'ആദ്യ സംഖ്യ × 0.80 = 160. അതിനാൽ ആദ്യ സംഖ്യ = 160 ÷ 0.8 = 200.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു വാഹനത്തിന്റെ വേഗം 45 കി.മീ./മണിക്കൂർ. 2 മണിക്കൂർ 40 മിനിറ്റിൽ സഞ്ചരിക്കുന്ന ദൂരം കണ്ടെത്തുക.', '', '', '', '', '2 മണിക്കൂർ 40 മിനിറ്റ് = 8/3 മണിക്കൂർ. ദൂരം = 45 × 8/3 = 120 കിലോമീറ്റർ.', '2 മണിക്കൂർ 40 മിനിറ്റ് = 8/3 മണിക്കൂർ. ദൂരം = 45 × 8/3 = 120 കിലോമീറ്റർ.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു വിദ്യാർത്ഥിക്ക് 5 വിഷയങ്ങളിൽ 70, 65, 80, 75, 60 മാർക്ക് ലഭിച്ചു. ശരാശരി കണ്ടെത്തുക.', '', '', '', '', 'ആകെ = 350. ശരാശരി = 350 ÷ 5 = 70.', 'ആകെ = 350. ശരാശരി = 350 ÷ 5 = 70.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു വ്യാപാരി 1200 രൂപയ്ക്ക് വാങ്ങിയ വസ്തു 10% ലാഭത്തിൽ വിൽക്കുന്നു. വിൽപ്പനവില കണ്ടെത്തുക.', '', '', '', '', 'ലാഭം = 1200 × 10/100 = 120. വിൽപ്പനവില = 1320 രൂപ.', 'ലാഭം = 1200 × 10/100 = 120. വിൽപ്പനവില = 1320 രൂപ.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു വസ്തുവിന് 20% ഇളവ് നൽകിയ ശേഷം വില 800 രൂപയായി. അടയാളപ്പെടുത്തിയ വില കണ്ടെത്തുക.', '', '', '', '', 'അടച്ച വില 80% ആണ്. അടയാളപ്പെടുത്തിയ വില = 800 ÷ 0.8 = 1000 രൂപ.', 'അടച്ച വില 80% ആണ്. അടയാളപ്പെടുത്തിയ വില = 800 ÷ 0.8 = 1000 രൂപ.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു ടാങ്ക് 12 മിനിറ്റിൽ നിറയുന്നു. അതേ നിരക്കിൽ 3 ടാങ്കുകൾ നിറയ്ക്കാൻ എത്ര സമയം വേണം?', '', '', '', '', 'ഓരോ ടാങ്കിനും 12 മിനിറ്റ്. 3 ടാങ്കുകൾക്ക് 12 × 3 = 36 മിനിറ്റ്.', 'ഓരോ ടാങ്കിനും 12 മിനിറ്റ്. 3 ടാങ്കുകൾക്ക് 12 × 3 = 36 മിനിറ്റ്.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു ജോലിയുടെ 40% പൂർത്തിയായി. ആകെ 250 യൂണിറ്റ് ജോലി ആണെങ്കിൽ പൂർത്തിയായത് എത്ര?', '', '', '', '', '250 × 40 ÷ 100 = 100 യൂണിറ്റ്.', '250 × 40 ÷ 100 = 100 യൂണിറ്റ്.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു സംഖ്യയുടെ 30%യും 20%യും തമ്മിലുള്ള വ്യത്യാസം 25 ആണെങ്കിൽ സംഖ്യ കണ്ടെത്തുക.', '', '', '', '', 'വ്യത്യാസം = 10% സംഖ്യ. 10% = 25 ആയതിനാൽ സംഖ്യ = 250.', 'വ്യത്യാസം = 10% സംഖ്യ. 10% = 25 ആയതിനാൽ സംഖ്യ = 250.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു ക്ലാസിൽ ആൺകുട്ടികളും പെൺകുട്ടികളും 3:2 എന്ന അനുപാതത്തിലാണ്. ആകെ 40 പേർ ഉണ്ടെങ്കിൽ ഓരോ വിഭാഗവും എത്ര?', '', '', '', '', 'ആകെ ഭാഗങ്ങൾ 5. ഒരു ഭാഗം = 40 ÷ 5 = 8. ആൺകുട്ടികൾ 24, പെൺകുട്ടികൾ 16.', 'ആകെ ഭാഗങ്ങൾ 5. ഒരു ഭാഗം = 40 ÷ 5 = 8. ആൺകുട്ടികൾ 24, പെൺകുട്ടികൾ 16.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു നിക്ഷേപത്തിന്റെ മൂല്യം 5000 രൂപ. 3 വർഷം കഴിഞ്ഞ് 900 രൂപ ലളിത പലിശ ലഭിച്ചു. പലിശനിരക്ക് കണ്ടെത്തുക.', '', '', '', '', 'നിരക്ക് = 900 × 100 ÷ (5000 × 3) = 6%.', 'നിരക്ക് = 900 × 100 ÷ (5000 × 3) = 6%.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു സംഖ്യയുടെ 2/3 ഭാഗം 50 ആണെങ്കിൽ സംഖ്യ കണ്ടെത്തുക.', '', '', '', '', 'സംഖ്യ = 50 × 3 ÷ 2 = 75.', 'സംഖ്യ = 50 × 3 ÷ 2 = 75.'),
('MAL-Aptitude', 'മലയാളം', 'വിസ്തൃത ഉത്തരം', 'കഠിനം', '5', 'ഒരു വ്യക്തി ആദ്യ ദിവസം 10 കിലോമീറ്ററും രണ്ടാം ദിവസം 15 കിലോമീറ്ററും മൂന്നാം ദിവസം 20 കിലോമീറ്ററും സഞ്ചരിച്ചു. ശരാശരി ദൂരം കണ്ടെത്തുക.', '', '', '', '', 'ആകെ = 45 കിലോമീറ്റർ. ദിവസങ്ങൾ = 3. ശരാശരി = 15 കിലോമീറ്റർ.', 'ആകെ = 45 കിലോമീറ്റർ. ദിവസങ്ങൾ = 3. ശരാശരി = 15 കിലോമീറ്റർ.'),
('MAL-Aptitude', 'മലയാളം', 'ഒറ്റ തിരഞ്ഞെടുപ്പ്', 'എളുപ്പം', '1', 'പ്രതിശതമാനം കണ്ടെത്തുന്നതിനുള്ള അടിസ്ഥാന സൂത്രവാക്യം എന്താണ്?', '(ഭാഗിക മൂല്യം ÷ ആകെ മൂല്യം) × 100', '(ആകെ മൂല്യം ÷ ഭാഗിക മൂല്യം) × 100', 'ഭാഗിക മൂല്യം × ആകെ മൂല്യം', 'ഭാഗിക മൂല്യം + ആകെ മൂല്യം', 'അ', 'പ്രതിശതമാനം = (ഭാഗിക മൂല്യം ÷ ആകെ മൂല്യം) × 100.'),
('MAL-Aptitude', 'മലയാളം', 'ശരി അല്ലെങ്കിൽ തെറ്റ്', 'എളുപ്പം', '1', 'ഒരു സംഖ്യയുടെ ഇരട്ടിയും അതിന്റെ പകുതിയും തമ്മിലുള്ള ബന്ധം എന്താണ്?', 'സരി', 'തെറ്റ്', '', '', 'സരി', 'ഒരു സംഖ്യ x ആണെങ്കിൽ അതിന്റെ ഇരട്ടി 2x, പകുതി x/2; അതിനാൽ 2x, x/2ന്റെ നാല് മടങ്ങാണ്.');